catalog_script_client.script:
function onSubmit() {

    if (typeof spModal != 'undefined' && !g_form._hasConfirmed) {
        spModal.open({
            message: 'By submitting this request, you confirm that you understand the cost of the license will be charged to your unit. The request will be sent to your immediate manager for approval before the license is assigned.You will receive a confirmation once the request has been processed.',
            title: 'Confirmation',
            buttons: [{
                    label: 'Cancel',
                    cancel: true
                },
                {
                    label: 'Ok',
                    primary: true
                }
            ]
        }).then(function(confirm) {
            if (confirm) {
                g_form._hasConfirmed = true;
                if (typeof g_form.orderNow != 'undefined') {
                    g_form.orderNow();
                } else {
                    g_form.submit();
                }
            }
        });
        return false;
    }
}
